package mod.cdv.tnpc.tactical;import java.util.*;public class CalmBrain{static Map<Object,State> states=new WeakHashMap<>();static State state(Object n){return states.computeIfAbsent(n,k->new State());}static boolean gun(Object n){return ((fixture.Entity)n).getMainHandItem().id.equals("tacz:gun");}static void crouch(Object n,boolean v){((fixture.Entity)n).shift=v;}static boolean alive(Object n){return n!=null&&((fixture.Entity)n).alive;}static boolean allied(Object n,Object o){return false;}static boolean visible(Object n,Object o){return ((fixture.Entity)n).visible&&((fixture.Entity)o).visible;}static void face(Object n,Object t){}static void path(Object n,State s,long now,double x,double y,double z,double speed){((fixture.Entity)n).navigation.moveTo(x,y,z,speed);s.nextPath=now+10;}static void error(String n,Exception e){throw new AssertionError(n,e);}static final class State{Object target;Object corpse;long reactAt,seen,nextPath,nextShot;double x,y,z;int zombies;}}